const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');
const { fork } = require('node:child_process');
const { once } = require('node:events');
const repo = process.argv[2];
const { sanitizeTestEnv } = require(path.join(repo, 'test/test-env'));
const { WebSocket, WebSocketServer } = require(path.join(repo, 'node_modules/ws'));
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'r5-relay-'));
const home = path.join(root, 'home');
const dish = path.join(home, '.pi/dish');
fs.mkdirSync(dish, { recursive: true });
fs.mkdirSync(path.join(home, '.pi/agent/sessions'), { recursive: true });
fs.mkdirSync(path.join(root, 'tmux'));
fs.mkdirSync(path.join(root, 'bin'));
const results = [];
const requests = [];
const timers = new Set();
let child;
const later = (fn, ms) => { const timer = setTimeout(() => { timers.delete(timer); fn(); }, ms); timers.add(timer); };
const peer = http.createServer((req, res) => {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    requests.push({ method: req.method, url: req.url, headers: req.headers, body });
    const url = new URL(req.url, 'http://peer');
    const json = (value, status = 200) => { res.writeHead(status, { 'content-type': 'application/json', 'access-control-allow-origin': 'https://peer.invalid', 'x-peer': 'retained' }); res.end(JSON.stringify(value)); };
    if (url.pathname === '/api/host') return json({ hostId: 'r5-peer', label: 'fixture', version: '1', capabilities: {} });
    if (url.pathname === '/api/sse') {
      res.writeHead(200, { 'content-type': 'text/event-stream', 'access-control-allow-origin': '*', 'x-peer': 'retained' });
      res.write('data: first\n\n');
      later(() => res.end('data: after-idle\n\n'), 10_500);
      return;
    }
    if (url.pathname === '/api/slow') return later(() => json({ delayed: true }), 8_000);
    if (url.pathname.endsWith('/hang') || url.pathname === '/page/hang') return;
    if (url.pathname.startsWith('/api/comments')) {
      if (url.searchParams.has('overflow')) { res.writeHead(200); return res.end('x'.repeat(65_537)); }
      if (url.searchParams.has('boundary')) { res.writeHead(202); return res.end('x'.repeat(65_536)); }
      if (url.searchParams.has('empty')) { res.writeHead(200); return res.end(); }
      return json({ owner: 'peer', method: req.method, body: body ? JSON.parse(body) : null }, 201);
    }
    if (url.pathname === '/api/pages') {
      const mode = body && JSON.parse(body).mode;
      res.setHeader('content-type', 'application/json');
      if (mode === 'malformed') return res.end('{not-json');
      if (mode === 'overflow') return res.end('x'.repeat(65_537));
      return json({ token: 'minted', url: 'https://peer.invalid/page/minted', extra: 'kept' }, 201);
    }
    if (url.pathname === '/api/notfound') return json({ peer404: true }, 404);
    if (url.pathname === '/api/servererror') return json({ peer500: true }, 500);
    if (url.pathname.startsWith('/page/')) {
      if (url.pathname === '/page/gone' || url.pathname.endsWith('/missing.css') || url.pathname === '/page/file/') { res.writeHead(404); return res.end('peer404'); }
      res.writeHead(200, { 'content-type': 'text/html', 'access-control-allow-origin': '*', 'x-peer': 'retained', 'set-cookie': ['a=1', 'b=2'] });
      return res.end('<html>peer document' + (req.headers['x-pi-dish-page-comments'] === 'off' ? '' : '<script src="artifact-comments.js"></script>') + '</html>');
    }
    return json({ method: req.method, url: req.url, headers: req.headers, body });
  });
});
const wss = new WebSocketServer({ noServer: true });
peer.on('upgrade', (req, socket, head) => {
  assert.equal(req.headers.authorization, 'Bearer peer-secret');
  assert.equal(req.headers.origin, undefined);
  wss.handleUpgrade(req, socket, head, ws => ws.on('message', data => ws.send(data)));
});
const auth = { Authorization: 'Bearer hub-secret' };
const fetchHub = (base, route, init = {}) => fetch(base + route, { ...init, headers: { ...auth, ...init.headers }, signal: AbortSignal.timeout(25_000) });
const record = (name, facts = {}) => { results.push({ name, ...facts }); console.log('PASS', name, JSON.stringify(facts)); };
(async () => {
  console.log('R5 smoke running');
  await new Promise(resolve => peer.listen(0, '127.0.0.1', resolve));
  const peerPort = peer.address().port;
  fs.writeFileSync(path.join(root, 'bin/ssh'), '#!/bin/sh\nsleep 3\nexec ' + JSON.stringify(process.execPath) + ' ' + JSON.stringify(path.join(repo, 'test/fixtures/fake-ssh.js')) + ' "$@"\n', { mode: 0o755 });
  fs.writeFileSync(path.join(dish, 'settings.json'), JSON.stringify({ remotes: [
    { name: 'peer', url: `http://127.0.0.1:${peerPort}`, token: 'peer-secret' },
    { name: 'hang', url: `http://127.0.0.1:${peerPort}`, token: 'peer-secret' },
    { name: 'ssh', sshDest: 'fixture@isolated', remotePort: peerPort, token: 'peer-secret' },
  ] }));
  fs.writeFileSync(path.join(dish, 'fleet-artifacts.json'), JSON.stringify(Object.fromEntries(['page', 'file', 'gone', 'hang'].map(token => [token, { host: 'peer', kind: 'page', createdAt: 1 }]))));
  const bootstrap = path.join(root, 'boot.cjs');
  fs.writeFileSync(bootstrap, `const server = require(${JSON.stringify(path.join(repo, 'server.js'))}); server.on('listening', () => process.send({ port: server.address().port }));`);
  const env = sanitizeTestEnv(process.env);
  Object.assign(env, { HOME: home, TMUX_TMPDIR: path.join(root, 'tmux'), PATH: path.join(root, 'bin') + ':' + env.PATH, PI_DISH_TOKEN: 'hub-secret', PI_DISH_SHARE_PORT: '0', PI_DISH_SHARE_BASE_URL: 'https://hub.invalid' });
  delete env.TMUX;
  delete env.SSH_AUTH_SOCK;
  child = fork(bootstrap, [], { env, stdio: ['ignore', 'pipe', 'pipe', 'ipc'] });
  let output = '', errors = '';
  child.stdout.on('data', chunk => { output += chunk; });
  child.stderr.on('data', chunk => { errors += chunk; });
  const [ready] = await once(child, 'message');
  const base = `http://127.0.0.1:${ready.port}`;
  for (let i = 0; !/share listener at http:\/\/127.0.0.1:(\d+)/.test(output); i++) { if (i > 300) throw new Error(errors + output); await new Promise(r => setTimeout(r, 10)); }
  const publicBase = /share listener at (http:\/\/127.0.0.1:\d+)/.exec(output)[1];
  const long = [
    (async () => {
      const start = Date.now();
      const response = await fetchHub(base, '/hosts/peer/api/sse', { headers: { 'accept-encoding': 'gzip' } });
      assert.equal(response.headers.get('content-encoding'), null);
      assert.equal(response.headers.get('access-control-allow-origin'), null);
      const reader = response.body.getReader();
      const first = await reader.read();
      assert.match(Buffer.from(first.value).toString(), /data: first/);
      const firstMs = Date.now() - start;
      assert.ok(firstMs < 3000, `SSE buffered ${firstMs}ms`);
      let rest = '';
      for (;;) { const next = await reader.read(); if (next.done) break; rest += Buffer.from(next.value).toString(); }
      assert.match(rest, /after-idle/);
      record('unbuffered identity SSE survives first-byte window', { firstMs, durationMs: Date.now() - start });
    })(),
    (async () => {
      const start = Date.now();
      const response = await fetchHub(base, '/hosts/ssh/api/slow');
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { delayed: true });
      const durationMs = Date.now() - start;
      assert.ok(durationMs >= 10_500, 'fixture setup+peer delay must cross original10s window');
      record('SSH fixture setup excluded from first-response deadline', { durationMs, setupDelayMs: 3000, peerDelayMs: 8000, transport: 'real HTTP over delayed fixture Unix forward; not real SSH daemon' });
    })(),
    (async () => {
      const start = Date.now();
      const response = await fetchHub(base, '/hosts/hang/api/hang');
      assert.equal(response.status, 502);
      assert.equal((await response.json()).reason, 'timeout');
      const durationMs = Date.now() - start;
      assert.ok(durationMs >= 9800 && durationMs < 15_000);
      const retryStart = Date.now();
      assert.equal((await fetchHub(base, '/hosts/hang/api/echo')).status, 502);
      assert.ok(Date.now() - retryStart < 1500);
      record('API timeout and breaker short circuit', { durationMs });
    })(),
    (async () => {
      const response = await fetch(publicBase + '/page/hang', { signal: AbortSignal.timeout(20_000) });
      assert.equal(response.status, 502);
      assert.equal(await response.text(), 'Host unavailable');
      const alive = await fetchHub(base, '/hosts/peer/api/echo');
      assert.equal(alive.status, 200);
      record('public timeout preserves no-breaker policy');
    })(),
    (async () => {
      const response = await fetchHub(base, '/api/comments/hang?pageToken=page');
      assert.equal(response.status, 502);
      assert.equal((await response.json()).reason, 'timeout');
      const alive = await fetchHub(base, '/hosts/peer/api/echo');
      assert.equal(alive.status, 200);
      record('comment timeout preserves no-breaker policy');
    })(),
  ];
  let response = await fetchHub(base, '/hosts/peer/api/echo?x=1', { method: 'POST', headers: { 'content-type': 'application/json', Origin: 'https://caller.invalid', Cookie: 'caller=yes' }, body: '{ raw invalid JSON' });
  assert.equal(response.headers.get('x-peer'), 'retained');
  assert.equal(response.headers.get('access-control-allow-origin'), null);
  let seen = await response.json();
  assert.equal(seen.body, '{ raw invalid JSON');
  assert.equal(seen.headers.authorization, 'Bearer peer-secret');
  assert.equal(seen.headers.origin, undefined);
  assert.equal(seen.headers.cookie, 'caller=yes');
  record('raw API body and credential policy');
  const beforeUnknown = requests.length;
  assert.equal((await fetch(publicBase + '/page/unmapped')).status, 404);
  assert.equal(requests.length, beforeUnknown);
  assert.equal((await fetch(publicBase + '/api/host')).status, 404);
  assert.equal((await fetch(publicBase + '/hosts/peer/api/echo')).status, 404);
  response = await fetch(publicBase + '/page/page', { headers: { Authorization: 'Bearer caller-secret', Origin: 'https://caller.invalid', Cookie: 'caller=yes', 'X-Secret': 'hidden', Accept: 'text/html', Range: 'bytes=0-', 'If-None-Match': 'v1' } });
  assert.equal(response.status, 200);
  assert.equal(response.headers.get('access-control-allow-origin'), null);
  assert.equal(response.headers.get('x-peer'), 'retained');
  assert.deepEqual(response.headers.getSetCookie(), ['a=1', 'b=2']);
  assert.doesNotMatch(await response.text(), /artifact-comments/);
  seen = requests.findLast(r => r.url === '/page/page');
  assert.equal(seen.headers.cookie, undefined);
  assert.equal(seen.headers['x-secret'], undefined);
  assert.equal(seen.headers.origin, undefined);
  assert.equal(seen.headers.authorization, 'Bearer peer-secret');
  assert.equal(seen.headers.range, 'bytes=0-');
  assert.equal(seen.headers['if-none-match'], 'v1');
  assert.equal(seen.headers['x-pi-dish-page-comments'], 'off');
  assert.match(await (await fetch(base + '/page/page')).text(), /artifact-comments/);
  record('public listener admission header allowlist and response filter');
  response = await fetchHub(base, '/hosts/peer/api/pages', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{}' });
  assert.equal(response.status, 201);
  assert.deepEqual(await response.json(), { token: 'minted', path: '/page/minted', url: 'https://hub.invalid/page/minted', extra: 'kept' });
  for (const [mode, expected] of [['malformed', '{not-json'], ['overflow', 'x'.repeat(65_537)]]) {
    response = await fetchHub(base, '/hosts/peer/api/pages', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ mode }) });
    assert.equal(await response.text(), expected);
  }
  record('artifact rewriting malformed JSON and overflow streaming');
  response = await fetchHub(base, '/api/comments', { method: 'POST', headers: { 'content-type': 'application/json' }, body: '{ "target": { "pageToken": "page" }, "body": "hi" }' });
  assert.equal(response.status, 201);
  assert.deepEqual((await response.json()).body, { target: { pageToken: 'page' }, body: 'hi' });
  seen = requests.findLast(r => r.url === '/api/comments');
  assert.equal(seen.body, '{"target":{"pageToken":"page"},"body":"hi"}');
  assert.equal(seen.headers['content-length'], String(Buffer.byteLength(seen.body)));
  response = await fetchHub(base, '/api/comments?pageToken=page&boundary=1');
  assert.equal(response.status, 202);
  assert.equal(await response.text(), 'x'.repeat(65_536));
  response = await fetchHub(base, '/api/comments?pageToken=page&overflow=1');
  assert.equal(response.status, 502);
  assert.match((await response.json()).error, /oversized comment response/);
  assert.equal(await (await fetchHub(base, '/api/comments?pageToken=page&empty=1')).text(), '{}');
  record('parsed comment forwarding and exact bounded response policies');
  assert.equal((await fetch(base + '/page/page/missing.css')).status, 404);
  assert.equal((await fetch(base + '/page/page')).status, 200);
  response = await fetch(base + '/page/file/?q=1', { redirect: 'manual' });
  assert.equal(response.status, 302);
  assert.equal(response.headers.get('location'), '/page/file?q=1');
  assert.equal((await fetch(base + '/page/gone')).status, 404);
  const mapped = JSON.parse(fs.readFileSync(path.join(dish, 'fleet-artifacts.json')));
  assert.ok(mapped.file && mapped.page && mapped.minted);
  assert.equal(mapped.gone, undefined);
  response = await fetchHub(base, '/hosts/peer/api/notfound');
  assert.equal(response.status, 404);
  assert.deepEqual(await response.json(), { peer404: true });
  assert.equal((await fetchHub(base, '/hosts/peer/api/servererror')).status, 500);
  assert.equal((await fetchHub(base, '/hosts/peer/api/echo')).status, 200);
  record('remote404 ownership pruning slash redirect and HTTP500 no-breaker');
  const ws = new WebSocket(base.replace('http:', 'ws:') + '/hosts/peer/api/sessions/fixture/terminal', { headers: auth });
  await once(ws, 'open');
  const echoed = once(ws, 'message');
  ws.send('R5 binary splice');
  assert.equal((await echoed)[0].toString(), 'R5 binary splice');
  ws.close(); await once(ws, 'close');
  record('real WS bidirectional splice with credential replacement');
  await Promise.all(long);
  fs.writeFileSync('/tmp/r5-relay-smoke-result.json', JSON.stringify({ runtime: process.version, results, stderr: errors, limits: ['SSH setup timing uses existing fake-ssh.js delayed3s, not actual daemon', 'No browser implementation/runtime mapping changed', 'Linux only'] }, null, 2) + '\n');
  console.log('R5 smoke complete', results.length);
})().catch(error => { console.error(error); process.exitCode = 1; }).finally(async () => {
  if (child && child.exitCode === null) { const exited = once(child, 'exit'); child.kill('SIGTERM'); await exited; }
  for (const timer of timers) clearTimeout(timer);
  for (const client of wss.clients) client.terminate();
  wss.close();
  peer.closeAllConnections();
  await new Promise(resolve => peer.close(resolve));
  fs.rmSync(root, { recursive: true, force: true });
});
